const webhookBody = $('Webhook').item.json.body || {};
const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const inbox = webhookBody.inbox || {};
const inboxId = inbox.id || conversation.inbox_id || 0;
const channel = conversation.channel || '';
const labels = conversation.labels || [];

// If conversation is marked as human, do NOT let AI agent intervene!
if (Array.isArray(labels) && labels.includes('human')) {
  return [];
}

return {
  json: {
    conversation_id: conversation.id || 13,
    account_id: account.id || 1,
    inbox_id: inboxId,
    channel: channel,
    message: webhookBody.content || ''
  }
};

// 1. Obtener la respuesta de la IA
const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json.response || "";

// 2. Extraer datos del webhook de forma segura (.first() en vez de .item)
let webhookRaw = {};
let webhookBody = {};
try {
  webhookRaw = $('Webhook').first().json || {};
  webhookBody = webhookRaw.body ? webhookRaw.body : webhookRaw;
} catch (e) {
  webhookBody = {};
}

const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const inbox = webhookBody.inbox || {};
const sender = conversation.meta?.sender || webhookBody.sender || {};
const customAttrs = conversation.custom_attributes || {};
const contactCustomAttrs = sender.custom_attributes || {};

const conversationId = conversation.id || 13;
const accountId = account.id || 1;
const inboxId = Number(inbox.id || conversation.inbox_id || 0);
const channel = conversation.channel || inbox.channel_type || "";

// 3. Formatear según canal (Meta / WhatsApp / Instagram vs Telegram)
let formattedText = aiResponse;
if (channel.includes("Whatsapp") || channel.includes("Facebook") || channel.includes("Instagram") || channel.includes("Api")) {
  formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');
  formattedText = formattedText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
}

// 4. Determinar si es WhatsApp y resolver instancia y remoteJid
// Resolver instance de múltiples fuentes posibles
let instance = webhookRaw.instance || webhookBody.instance || customAttrs.instance || contactCustomAttrs.instance || '';
let remoteJid = webhookRaw.data?.key?.remoteJid || '';

const senderIdentifier = String(sender.identifier || '');
const senderPhone = String(sender.phone_number || '');

if (!remoteJid) {
  if (senderIdentifier.includes('@s.whatsapp.net')) {
    remoteJid = senderIdentifier;
  } else if (senderIdentifier.startsWith('wa_')) {
    remoteJid = senderIdentifier.replace(/^wa_/, '') + '@s.whatsapp.net';
  } else if (senderPhone) {
    const cleanPhone = senderPhone.replace(/\D/g, '');
    if (cleanPhone) remoteJid = cleanPhone + '@s.whatsapp.net';
  } else if (senderIdentifier && /^\d+$/.test(senderIdentifier)) {
    remoteJid = senderIdentifier + '@s.whatsapp.net';
  }
}

// Check if inbox is WhatsApp (not Instagram inboxes 13/14, and channel is Whatsapp or Api with phone/instance)
const isInstagram = (inboxId === 13 || inboxId === 14 || channel.toLowerCase().includes('instagram'));
let isWhatsapp = false;

if (!isInstagram) {
  if (channel.toLowerCase().includes('whatsapp') || Boolean(webhookRaw.instance) || Boolean(instance)) {
    isWhatsapp = true;
  } else if (remoteJid && (channel.includes('Api') || inbox.channel_type === 'Channel::Api')) {
    isWhatsapp = true;
  }
}

// Default instance if missing for WhatsApp channel
if (isWhatsapp && !instance) {
  instance = 'TTvAlertsMovistar';
}

// 5. Calcular delay realista de simulación humana (entre 2 y 5 segundos)
// ~30 caracteres = 2s, ~100 caracteres = 3.5s, ~200+ caracteres = 5s
const charCount = formattedText.length;
const calculatedDelay = Math.min(5, Math.max(2, Math.round(charCount * 0.015 + 2)));

return {
  json: {
    content: formattedText,
    conversation_id: conversationId,
    account_id: accountId,
    inbox_id: inboxId,
    channel: channel,
    is_whatsapp: isWhatsapp,
    instance: instance,
    remoteJid: remoteJid,
    delay_seconds: calculatedDelay
  }
};

