        inbox_id: inboxId,
        contact_id: contactId,
        custom_attributes: {
          zernio_conversation_id: zernioConvId,
          instagram_username: participantUsername,
          participant_id: participantId,
          zernio_account_id: accountId
        }
      },
      json: true
    });
    conversationId = createConvRes.id;
  }

