  const content = body.content || '';
  if (!content.trim()) {
    return [{ json: { ignored: true, reason: 'empty content' } }];
  }

  const conversation = body.conversation || {};
  const inbox = body.inbox || {};
  const inboxId = Number(inbox.id || conversation.inbox_id || 0);

  // Only handle Instagram inboxes: 13 (TVTotal24) and 14 (TotalTv USA)
  if (inboxId !== 13 && inboxId !== 14) {
    return [{ json: { ignored: true, reason: 'not an instagram inbox (13 or 14)', inboxId } }];
  }

  // Determine Zernio credentials based on inbox
  let zernioApiKey = '';
  let accountId = '';

  if (inboxId === 13) {
    // TVTotal24
    zernioApiKey = 'sk_ad87ef37da3670603641edd90966dfa359fe77f6c4a23d10f807b707c1b5cbf1';
    accountId = '6a8667d577555aae0139eca3';
  } else if (inboxId === 14) {
    // TotalTv USA
    zernioApiKey = 'sk_997f75cb81b8ed42a9764a99aab59b5a1389a3a91c29b1311fe8d31e4e337135';
    accountId = '6a86600b77555aae01387fc7';
  }

  const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
  const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

  // Extract Instagram participant ID (e.g. 7086168948163452)
  let participantId = null;

  // 1. Check conversation sender identifier
  const sender = conversation.meta?.sender || body.sender || {};
  if (sender.identifier && sender.identifier.startsWith('ig_')) {
    participantId = sender.identifier.replace(/^ig_/, '');
  }

  // 2. Check conversation custom attributes
  const customAttrs = conversation.custom_attributes || {};
  if (!participantId && customAttrs.participant_id) {
    participantId = customAttrs.participant_id;
  }

  // 3. Query Chatwoot API if still missing
  if (!participantId && conversation.id) {
    try {
      const cRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/conversations/${conversation.id}`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      const s = cRes.meta?.sender || {};
      if (s.identifier && s.identifier.startsWith('ig_')) {
        participantId = s.identifier.replace(/^ig_/, '');
      } else if (cRes.custom_attributes?.participant_id) {
        participantId = cRes.custom_attributes.participant_id;
      }
    } catch (e) {}
  }

  // 4. Check contact directly if still missing
  if (!participantId && (conversation.contact_id || sender.id)) {
    try {
      const contactId = conversation.contact_id || sender.id;
      const ctRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/contacts/${contactId}`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      const ident = ctRes.payload?.identifier || '';
      if (ident.startsWith('ig_')) {
        participantId = ident.replace(/^ig_/, '');
      } else if (ctRes.payload?.custom_attributes?.participant_id) {
        participantId = ctRes.payload.custom_attributes.participant_id;
      }
    } catch (e) {}
  }

  if (!participantId) {
    return [{ json: { error: 'Missing Instagram participantId', conversationId: conversation.id } }];
  }

  // Call Zernio API with Idempotency-Key based on Chatwoot message ID
  const chatwootMsgId = String(body.id || '');
  const headers = {
    'Authorization': `Bearer ${zernioApiKey}`,
    'Content-Type': 'application/json'
  };

  if (chatwootMsgId) {
    headers['Idempotency-Key'] = `chatwoot_msg_${chatwootMsgId}`;
  }

  const zRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.zernio.com/v1/inbox/conversations/${participantId}/messages`,
    headers: headers,
    body: {
      message: content,
      accountId: accountId
    },
    json: true
  });

  return [{
    json: {
      success: true,
      inbox_id: inboxId,
      participantId: participantId,
      chatwoot_msg_id: chatwootMsgId,
      zernio_response: zRes
    }
  }];
} catch (err) {
  return [{ json: { error: err.message, stack: err.stack } }];
}
